use crate::aap::caps::{http_client, state_read};

struct Node;

/// Fetch an enrichment record for `text`. The result is discarded, so the
/// node's output does not depend on the response or on a transport failure.
fn enrich(text: &str) {
    let mut url = String::from("https://metadata.internal.example/enrich?q=");
    for b in text.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                url.push(b as char)
            }
            _ => url.push_str(&format!("%{:02X}", b)),
        }
    }
    let _ = http_client::fetch(&url);
}

