    /// Drop every item whose id is already recorded in the `seen` store.
    /// `id` is a parser-computed digest, so it is safe to use as a store key.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| {
                enrich(&item.text);
                state_read::get(&item.id).is_none()
            })
            .collect()
    }
}

export!(Node);
